#include <array>
#include <vector>
#include <random>
#include <chrono>
#include <algorithm>
#include <iostream>
#include <cassert>
#include <cmath>
#include <cstdint>
using namespace std;
#include "meta3773_five_patch_over_data.hpp"
struct Gate{int op,a,b;};
struct Program{array<Gate,G> g;array<int,8> choice;int out;};
struct Evaluation{int err,cost;bool bad;array<int,N+G> rep,pa,pb;vector<int> active;uint64_t output;};
array<uint64_t,R> raw_inputs;
uint64_t target;
vector<pair<int,int>> edges;
vector<pair<int,int>> free_gates(const Program&p){vector<pair<int,int>>answer;for(int i=0;i<8;i++){const auto&variant=free_variants[i][p.choice[i]];answer.insert(answer.end(),variant.begin(),variant.end());}assert(answer.size()==N-R);return answer;}
Evaluation evaluate(const Program&p){Evaluation e;array<uint64_t,N+G>v;array<int,256>slot;slot.fill(-1);for(int i=0;i<R;i++)v[i]=raw_inputs[i];int cur=R;for(int i=0;i<8;i++)for(auto[a,b]:free_variants[i][p.choice[i]]){assert(a<cur&&b<cur);v[cur++]=v[a]|v[b];}assert(cur==N);
 auto insert=[&](uint64_t value,int index){unsigned h=(value*11400714819323198485ull)>>56;while(slot[h]>=0&&v[slot[h]]!=value)h=(h+1)&255;if(slot[h]<0)slot[h]=index;return slot[h];};for(int i=0;i<N;i++)e.rep[i]=insert(v[i],i);
 for(int i=0;i<G;i++){int w=N+i;const auto&t=p.g[i];assert(t.a<w&&t.b<w);v[w]=t.op?(v[t.a]|v[t.b]):(v[t.a]&v[t.b]);e.pa[w]=e.rep[t.a];e.pb[w]=e.rep[t.b];e.rep[w]=insert(v[w],w);}e.output=v[p.out];e.err=__builtin_popcountll(e.output^target);array<bool,N+G>used{};auto visit=[&](auto&&self,int w)->void{w=e.rep[w];if(w<N||used[w])return;used[w]=true;self(self,e.pa[w]);self(self,e.pb[w]);e.active.push_back(w);};visit(visit,p.out);array<bool,N+G> raw_used{};vector<int>raw_active;auto raw_visit=[&](auto&&self,int w)->void{if(w<N||raw_used[w])return;raw_used[w]=true;self(self,p.g[w-N].a);self(self,p.g[w-N].b);raw_active.push_back(w);};raw_visit(raw_visit,p.out);if(raw_active.size()<e.active.size()){e.active=raw_active;for(int w=0;w<N+G;w++)e.rep[w]=w;for(int i=0;i<G;i++){e.pa[N+i]=p.g[i].a;e.pb[N+i]=p.g[i].b;}}e.cost=e.active.size();e.bad=false;for(int w:e.active)if(p.g[w-N].op==0&&(v[w]&target)&&(v[w]&~target))e.bad=true;return e;}
Program seed_program(mt19937_64&rng,int style){Program p;for(int i=0;i<8;i++)p.choice[i]=rng()%free_variants[i].size();vector<Gate>list;auto gate=[&](int op,int a,int b){int w=N+list.size();list.push_back({op,a,b});return w;};auto orlist=[&](vector<int>vs){shuffle(vs.begin(),vs.end(),rng);int w=vs[0];for(size_t i=1;i<vs.size();i++)w=gate(1,w,vs[i]);return w;};array<int,32>point_or{},star_or{};for(int i=0;i<K;i++)point_or[1<<i]=i;for(int m=1;m<32;m++)if(__builtin_popcount((unsigned)m)>1){int bit=m&-m;point_or[m]=gate(1,point_or[bit],point_or[m^bit]);}vector<vector<int>>neighbors(K);for(auto[a,b]:edges)neighbors[a].push_back(b);array<int,K>neighborhood{},star{};for(int i=0;i<K;i++){neighborhood[i]=orlist(neighbors[i]);star[i]=gate(0,i,neighborhood[i]);star_or[1<<i]=star[i];}for(int m=1;m<31;m++)if(__builtin_popcount((unsigned)m)>1){int bit=m&-m;star_or[m]=gate(1,star_or[bit],star_or[m^bit]);}for(int i=0;i<K;i++)gate(1,point_or[31^(1<<i)],neighborhood[i]);int roots[2][4]={{19,25,27,31},{17,24,25,29}};int all_lines=orlist(vector<int>(roots[style%2],roots[style%2]+4));vector<int>terms;if(rng()%2){int skipped=rng()%K;for(int i=0;i<K;i++)terms.push_back(i==skipped?((rng()%3)?neighborhood[i]:i):star[i]);}else{int subset;do{subset=1+(rng()%31);}while(__builtin_popcount((unsigned)subset)<2);terms.push_back(gate(0,point_or[subset],all_lines));for(int i=0;i<K;i++)if(!(subset>>i&1))terms.push_back(star[i]);}p.out=orlist(terms);assert(list.size()<=G);for(int i=0;i<G;i++)p.g[i]=i<(int)list.size()?list[i]:Gate{(int)(rng()%2),(int)(rng()%(N+i)),(int)(rng()%(N+i))};return p;}
uint64_t sample_mask;
array<uint64_t,N+G> wire_values(const Program&p,int forced=-1,uint64_t replacement=0){array<uint64_t,N+G>v;for(int i=0;i<R;i++)v[i]=raw_inputs[i];int at=R;for(int i=0;i<8;i++)for(auto[a,b]:free_variants[i][p.choice[i]])v[at++]=v[a]|v[b];assert(at==N);for(int i=0;i<G;i++){auto t=p.g[i];v[N+i]=(i==forced)?replacement:(t.op?(v[t.a]|v[t.b]):(v[t.a]&v[t.b]));}return v;}
Program guided_repair(const Program&p,const Evaluation&e,mt19937_64&rng,bool two){array<bool,G>raw{};vector<int>active;auto visit=[&](auto&&self,int w)->void{if(w<N||raw[w-N])return;int i=w-N;raw[i]=true;self(self,p.g[i].a);self(self,p.g[i].b);active.push_back(i);};visit(visit,p.out);if(active.empty())return p;int i=active[rng()%active.size()],j=-1;if(two){vector<int>spare;for(int k=0;k<i;k++)if(!raw[k])spare.push_back(k);if(spare.empty())return p;j=(rng()%4)?spare.back():spare[rng()%spare.size()];}
 auto v=wire_values(p),low_values=wire_values(p,i,0),high_values=wire_values(p,i,sample_mask);uint64_t low=low_values[p.out],care=low^high_values[p.out];if(!care)return p;int limit=N+(two?j:i);vector<int>prefix;for(int a=0;a<limit;a++)if(e.rep[a]==a)prefix.push_back(a);struct Candidate{Gate first,second;};vector<Candidate>choices;int besterr=e.err,seen=0;
 auto consider=[&](Candidate c,uint64_t value){uint64_t result=low|(value&care);if((result&target)!=target)return;int error=__builtin_popcountll(result^target);if(error>besterr)return;if(error<besterr){besterr=error;choices.clear();seen=0;}seen++;if(choices.size()<48)choices.push_back(c);else{int pick=rng()%seen;if(pick<48)choices[pick]=c;}};
 for(int a:prefix)for(int b:prefix)if(a<=b)for(int op=0;op<2;op++){uint64_t value=op?(v[a]|v[b]):(v[a]&v[b]);if(!two)consider({{op,a,b},{0,0,0}},value);else for(int c:prefix)for(int last=0;last<2;last++)consider({{op,a,b},{last,N+j,c}},last?(value|v[c]):(value&v[c]));}
 auto energy=[](const Evaluation&z){return 2.0*z.err+20.0*max(0,z.cost-TARGET)+0.002*z.cost+(z.bad?0:0.4);};Program best=p;double bestscore=energy(e);int ties=1;for(auto c:choices){Program q=p;if(two){q.g[j]=c.first;q.g[i]=c.second;}else q.g[i]=c.first;Evaluation f=evaluate(q);if(f.cost>TARGET||(f.output&target)!=target)continue;double score=energy(f);if(score<bestscore){bestscore=score;best=q;ties=1;}else if(score==bestscore&&rng()%++ties==0)best=q;}return best;}
void output_solution(const Program&p,const Evaluation&e,bool must=true){array<int,N+G>mapped;mapped.fill(-1);for(int i=0;i<N;i++)mapped[i]=i;vector<Gate>answer;for(int w:e.active){int a=mapped[e.pa[w]],b=mapped[e.pb[w]];assert(a>=0&&b>=0);mapped[w]=N+answer.size();answer.push_back({p.g[w-N].op,a,b});}int out=mapped[e.rep[p.out]];assert(out>=0);auto fg=free_gates(p);
 int differences=0;for(int mask=0;mask<(1<<R);mask++){vector<bool>val;for(int i=0;i<R;i++)val.push_back((mask>>i)&1);for(auto[a,b]:fg)val.push_back(val[a]||val[b]);assert(val.size()==N);for(auto t:answer)val.push_back(t.op?(val[t.a]||val[t.b]):(val[t.a]&&val[t.b]));bool f=false;for(auto[a,b]:edges)f=f||(val[a]&&val[b]);if(val[out]!=f)differences++;}if(must)assert(differences==0);
 cout<<"{\"stage\":\"diagnostic_patch\",\"free_ors\":[";for(size_t i=0;i<fg.size();i++){if(i)cout<<',';cout<<'['<<fg[i].first<<','<<fg[i].second<<']';}cout<<"],\"gates\":[";for(size_t i=0;i<answer.size();i++){auto t=answer[i];if(i)cout<<',';cout<<'['<<t.op<<','<<t.a<<','<<t.b<<']';}cout<<"],\"output\":"<<out<<",\"size\":"<<answer.size()<<",\"assembled_global_size\":"<<(BASE+answer.size())<<",\"physical_truth_table_verified\":"<<(differences==0?"true":"false")<<",\"physical_errors\":"<<differences<<"}"<<endl;}
int main(int argc,char**argv){assert(argc==3);int seconds=stoi(argv[1]);assert(seconds>0&&seconds<=180);uint64_t sd=stoull(argv[2]);mt19937_64 rng(sd);auto inD=[](int x){return x==0||x==1||x==3||x==9;};for(int i=0;i<K;i++)for(int j=0;j<(int)line_ids.size();j++)if(inD((point_ids[i]+line_ids[j])%13))edges.push_back({i,K+j});assert(edges.size()==4*K);vector<int>samples;for(auto[a,b]:edges)samples.push_back((1<<a)|(1<<b));int positives=samples.size();array<int,R>adj{};for(auto[a,b]:edges){adj[a]|=1<<b;adj[b]|=1<<a;}for(int m=0;m<(1<<R);m++){bool ind=true,maximal=true;for(auto[a,b]:edges)if((m>>a&1)&&(m>>b&1))ind=false;if(!ind)continue;for(int a=0;a<R;a++)if(!(m>>a&1)&&!(adj[a]&m))maximal=false;if(maximal)samples.push_back(m);}assert(samples.size()<=64);sample_mask=samples.size()==64?~0ull:((1ull<<samples.size())-1);target=(1ull<<positives)-1;for(int row=0;row<(int)samples.size();row++){int m=samples[row];for(int i=0;i<R;i++)if(m>>i&1)raw_inputs[i]|=1ull<<row;}
 cout<<"{\"stage\":\"start\",\"seed\":"<<sd<<",\"samples\":"<<samples.size()<<",\"genotype_gates\":"<<G<<",\"raw_inputs\":"<<R<<",\"free_or_count\":16,\"outside_points_in_order\":[4,5,7,8,9,10,11,12]}"<<endl;
 auto start=chrono::steady_clock::now();uint64_t iterations=0,restarts=0;int best=TARGET+1,bestbad=100,bestnear=100;Program p=seed_program(rng,0);Evaluation e=evaluate(p);assert((e.output&target)==target&&e.cost<=TARGET);if(e.err==0&&e.cost<=TARGET){output_solution(p,e);return 0;}vector<Program>pool;pool.push_back(p);auto value=[](const Evaluation&v){return 2.0*v.err+20.0*max(0,v.cost-TARGET)+0.002*v.cost+(v.bad?0:0.4);};double score=value(e);
 while(true){if(iterations%1024==0&&chrono::duration<double>(chrono::steady_clock::now()-start).count()>=seconds)break;if(iterations%800000==0){int style=rng()%4;p=style<3?seed_program(rng,style):pool[rng()%pool.size()];e=evaluate(p);assert((e.output&target)==target&&e.cost<=TARGET);if(e.err==0&&e.cost<=TARGET){output_solution(p,e);return 0;}score=value(e);restarts++;}
 Program q=p;if(iterations%32768==32767)q=guided_repair(p,e,rng,true);else if(iterations%512==511)q=guided_repair(p,e,rng,false);else{int changes=(rng()%12==0)?2:1;for(int step=0;step<changes;step++){int what=rng()%40;if(what==0){int i=rng()%8;q.choice[i]=rng()%free_variants[i].size();}else if(what<3)q.out=rng()%(N+G);else{int k=(rng()%4!=0&&!e.active.empty())?e.active[rng()%e.active.size()]-N:rng()%G;int which=rng()%3;if(which==0)q.g[k].op^=1;else if(which==1)q.g[k].a=rng()%(N+k);else q.g[k].b=rng()%(N+k);}}}

 Evaluation f=evaluate(q);double next=value(f);double phase=double(iterations%800000)/800000.0;double temperature=0.04+2.0*(1-phase)*(1-phase);bool allowed=f.cost<=TARGET&&(f.output&target)==target;bool accept=allowed&&(next<=score||generate_canonical<double,53>(rng)<exp((score-next)/temperature));if(accept){p=q;e=f;score=next;}if(f.err==0&&f.cost<best){best=f.cost;cout<<"{\"stage\":\"best\",\"iterations\":"<<iterations<<",\"size\":"<<best<<"}"<<endl;if(best<=TARGET){output_solution(q,f);return 0;}}if(f.err==0&&f.bad&&f.cost<bestbad){bestbad=f.cost;cout<<"{\"stage\":\"best_bad_and_patch\",\"size\":"<<bestbad<<"}"<<endl;output_solution(q,f);}
 if(f.cost<=TARGET&&(f.output&target)==target&&f.err<bestnear){bestnear=f.err;cout<<"{\"stage\":\"near_over_patch\",\"sample_errors\":"<<bestnear<<",\"size\":"<<f.cost<<"}"<<endl;output_solution(q,f,false);}
 if(e.cost<=TARGET&&(e.output&target)==target&&e.err<=5&&iterations%1000==0){if(pool.size()<16)pool.push_back(p);else pool[rng()%pool.size()]=p;}iterations++;}
 cout<<"{\"stage\":\"finished\",\"iterations\":"<<iterations<<",\"restarts\":"<<restarts<<",\"best_valid_size\":"<<best<<",\"seconds\":"<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"}"<<endl;}
